#!/usr/bin/env bash
# =============================================================================
#  apply-vendor-patches.sh — apply the tracked patches to the nzk_ui vendor
#  tree. `nzk_ui/vendor/` is git-ignored (it is regenerated by
#  `cargo vendor`), so a patch that must survive a fresh checkout is kept as a
#  tracked diff under `tools/patches/` and applied by this script.
#
#  Why a vendor patch at all (r27): the reference UI is Chromium, and on this
#  Linux host Chromium's glyph rasteriser does NOT apply vertical outline
#  hinting; vello's `hint(true)` both hints stems and rounds the glyph baseline
#  to an integer pixel, which measured whole-frame mae 1.3262 (sidebar 4.1451,
#  topbar 5.1309, canvas 0.2385). Turning hinting off (unhinted outline +
#  fractional baseline) is what matches the reference: mae 1.2122 (sidebar
#  3.7077, topbar 4.9883, canvas 0.2205), deterministic across runs
#  (fork sha b889767a…), evidence `evidence/v3launch/verify-r27/`.
#
#  Usage:
#    tools/apply-vendor-patches.sh          # idempotent: no-op when applied
#    tools/apply-vendor-patches.sh --check  # dry-run, exit 1 if a patch missing
#
#  After applying, rebuild nzk_ui the normal way:
#    cd "cs viewer builder" && . ./rust-env.sh \
#      && CARGO_TARGET_DIR="$PWD/native-csviewer/nzk_ui/target" \
#      && cd native-csviewer/nzk_ui && cargo build --release --offline
#  (the blitz-paint fingerprint is removed so cargo actually recompiles it).
# =============================================================================
set -euo pipefail

HERE="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"   # native-csviewer/tools
CRATE="$(cd -- "$HERE/.." && pwd -P)/nzk_ui"
PATCH_DIR="$HERE/patches"
CHECK=0
[ "${1:-}" = "--check" ] && CHECK=1

apply_patch() {
  local patch_file="$1" target="$2" marker="$3"
  if grep -qF "$marker" "$target"; then
    echo "apply-vendor-patches: already applied: $(basename "$patch_file")"
    return 0
  fi
  if [ "$CHECK" = 1 ]; then
    echo "apply-vendor-patches: MISSING: $(basename "$patch_file")" >&2
    return 1
  fi
  ( cd "$CRATE" && patch -p0 --forward --silent -i "$patch_file" )
  echo "apply-vendor-patches: applied: $(basename "$patch_file")"
}

apply_patch "$PATCH_DIR/blitz-paint-unhinted.patch" \
            "$CRATE/vendor/blitz-paint/src/text.rs" \
            "false, // hint"

# r28: Chromium clips a text input's inner editor at its CONTENT box, not at
# the padding box. #rootInput has `padding: 0 9px`, so the old padding-box clip
# let the value's ink run 9px too far right (ref ends x=334, fork x=343).
apply_patch "$PATCH_DIR/blitz-paint-input-content-clip.patch" \
            "$CRATE/vendor/blitz-paint/src/render.rs" \
            "cx.frame.content_box_path()"

# r32: Blitz's text-input editor only copied FontSize/LineHeight/Brush from the
# computed style into the Parley editor, so an author `font-family` on the
# control (e.g. `.text-input { font-family: var(--mono) }` from the real
# style.css) never reached the input's text layout: every text field shaped in
# Parley's default proportional sans, and the topbar repo-path chip fit ~3 more
# characters than the reference (topbar 4.8172 -> 4.4178, whole 1.0806 ->
# 1.0602). Copy the full computed font style instead.
apply_patch "$PATCH_DIR/blitz-dom-input-font.patch" \
            "$CRATE/vendor/blitz-dom/src/layout/construct.rs" \
            "FontStack(parley_style.font_stack.clone())"

if [ "$CHECK" = 0 ]; then
  # cargo checks per-file checksums of directory sources; a modified file needs
  # its checksum refreshed or the build fails with "the listed checksum …
  # changed". Also drop the crate fingerprint so the change is not skipped.
  ( cd "$CRATE" && python3 - <<'PY'
import hashlib, json
for cj, crate, rels in (
    ("vendor/blitz-paint/.cargo-checksum.json", "blitz-paint", ("src/text.rs", "src/render.rs")),
    ("vendor/blitz-dom/.cargo-checksum.json", "blitz-dom", ("src/layout/construct.rs",)),
):
    d = json.load(open(cj))
    for rel in rels:
        p = "vendor/" + crate + "/" + rel
        sha = hashlib.sha256(open(p, "rb").read()).hexdigest()
        if d["files"].get(rel) != sha:
            d["files"][rel] = sha
            json.dump(d, open(cj, "w"))
            print("apply-vendor-patches: refreshed", crate, "checksum", rel, sha[:16])
PY
  )
  rm -rf "$CRATE"/target/*/.fingerprint/blitz-paint-* 2>/dev/null || true
  rm -rf "$CRATE"/target/*/.fingerprint/blitz-dom-* 2>/dev/null || true
fi
echo "apply-vendor-patches: OK"
